import os,re,zipfile,html
root='documents/matters'
for dp, dns, fns in os.walk(root):
    for fn in fns:
        if not fn.lower().endswith('.docx') or 'settlement' not in fn.lower() and 'release' not in fn.lower() and 'stipulation' not in fn.lower():
            continue
        p=os.path.join(dp,fn)
        try:
            with zipfile.ZipFile(p) as z:
                x=z.read('word/document.xml').decode('utf-8','ignore')
            x=re.sub(r'</w:p>', '\n', x); x=re.sub(r'<w:tab[^>]*/>', '\t', x); x=re.sub(r'<[^>]+>','',x)
            x=html.unescape(x)
            lines=[re.sub(r'\s+',' ',s).strip() for s in x.splitlines()]
            hits=[]
            for i,line in enumerate(lines):
                low=line.lower()
                if any(k in low for k in ['$', 'million','thousand','settlement amount','settlement payment','aggregate','consideration','payment of','pay ','paid ']):
                    if line and len(line)<500: hits.append(line)
            print('\n###',p)
            for h in hits[:40]: print(h)
        except Exception as e: print('ERR',p,e)
PY","description":"Extract settlement document payment terms","timeoutMs":200000}

