import os,re,zipfile,html
rows=[]
for dp,dns,fns in os.walk('documents/matters'):
  for fn in fns:
    if not fn.lower().endswith('.docx') or not any(k in fn.lower() for k in ['settlement','release','stipulation']): continue
    p=os.path.join(dp,fn)
    try:
      with zipfile.ZipFile(p) as z: x=z.read('word/document.xml').decode('utf-8','ignore')
      x=re.sub(r'</w:p>', '\n', x); x=re.sub(r'<w:tab[^>]*/>', '\t', x); x=re.sub(r'<[^>]+>','',x); x=html.unescape(x)
      lines=[re.sub(r'\s+',' ',s).strip() for s in x.splitlines() if s.strip()]
      vals=[]; samples=[]
      for line in lines:
        l=line.lower()
        if any(k in l for k in ['settlement amount','settlement payment','aggregate settlement','total settlement','cash settlement','settlement consideration','amount of the settlement','settlement sum','settlement proceeds']):
          for m in re.finditer(r'\$\s*([0-9][0-9,]*(?:\.\d+)?)',line):
            v=float(m.group(1).replace(',','')); vals.append(v)
          if '$' in line or 'million' in l: samples.append(line[:220])
      if vals: rows.append((max(vals),p,samples[:2]))
    except: pass
for v,p,s in sorted(rows, reverse=True):
  if v>=100000:
    print(f'{v:,.0f}\t{p}\t'+' | '.join(s))
